package dev.rajivm.model;

import org.bson.Document;

public class User {
    private String id;
    private String name;
    private String email;

    public User() {}

    public User(String id, String name, String email) {
        this.id = id;
        this.name = name;
        this.email = email;
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public Document toDocument() {
        Document doc = new Document();
        if (id != null) doc.append("_id", id);
        doc.append("name", name);
        doc.append("email", email);
        return doc;
    }

    public static User fromDocument(Document doc) {
        if (doc == null) return null;
        User u = new User();
        Object id = doc.get("_id");
        if (id != null) u.setId(id.toString());
        u.setName(doc.getString("name"));
        u.setEmail(doc.getString("email"));
        return u;
    }
}

package dev.rajivm.mongo;

import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoClients;
import com.mongodb.client.MongoDatabase;

/**
 * Simple provider for a MongoClient. Reads connection string from environment variable MONGODB_URI
 * or falls back to mongodb://localhost:27017. Keeps a single shared client.
 */
public class MongoClientProvider {
    private static final String DEFAULT_URI = "mongodb://localhost:27017";
    private static volatile MongoClient client;

    private MongoClientProvider() {}

    public static MongoClient getClient() {
        if (client == null) {
            synchronized (MongoClientProvider.class) {
                if (client == null) {
                    String uri = System.getenv("MONGODB_URI");
                    if (uri == null || uri.isBlank()) {
                        uri = DEFAULT_URI;
                    }
                    client = MongoClients.create(uri);
                }
            }
        }
        return client;
    }

    public static MongoDatabase getDatabase(String dbName) {
        return getClient().getDatabase(dbName);
    }

    public static void close() {
        if (client != null) {
            client.close();
            client = null;
        }
    }
}

